it('should sort tasks by status', () => {
  // Arrange
  const computer = createTaskComputer();
  const tasks = [
    { id: '1', status: 'done' },
    { id: '2', status: 'pending' },
  ];

  // Act
  const result = computer.sortByStatus(tasks);

  // Assert
  expect(result[0].status).toBe('pending');
  expect(result[1].status).toBe('done');
});

